<?php defined('ALTUMCODE') || die();
if(!\Altum\Authentication::is_admin()) return;
if(isset($_GET['thread'])){require THEME_PATH.'views/partner/admin-coach-conversation.php';return;}
$filter=in_array($_GET['rating']??'',['up','down','open'],true)?$_GET['rating']:'all';
$before=max(1,(int)($_GET['before']??PHP_INT_MAX));
$where=$filter==='open'?" AND f.feedback_type='down' AND f.status='new'":($filter==='all'?'':" AND f.feedback_type='".$filter."'");
$conversation=max(0,(int)($_GET['conversation']??0));
if($conversation) $where.=' AND f.fcc_ai_conversation_id='.$conversation;
$conversation_query=$conversation?'&conversation='.$conversation:'';
$ratings=fcc_partner_rows("SELECT f.*,m.content,m.meta response_meta,c.public_id,u.name,(SELECT p.content FROM fcc_ai_messages p WHERE p.fcc_ai_conversation_id=f.fcc_ai_conversation_id AND p.role='user' AND p.fcc_ai_message_id<f.fcc_ai_message_id ORDER BY p.fcc_ai_message_id DESC LIMIT 1) question FROM fcc_ai_message_feedback f JOIN fcc_ai_messages m ON m.fcc_ai_message_id=f.fcc_ai_message_id JOIN fcc_ai_conversations c ON c.fcc_ai_conversation_id=f.fcc_ai_conversation_id JOIN users u ON u.user_id=f.user_id WHERE c.scope='internal_coach' AND c.assistant_type='coach' AND f.fcc_ai_message_feedback_id<? $where ORDER BY f.fcc_ai_message_feedback_id DESC LIMIT 31",[$before]);
$has_more=count($ratings)>30;$ratings=array_slice($ratings,0,30);
?>
<a class="fp-link" href="<?= url('partner/admin') ?>"><?= htmlspecialchars(fcc_t('← Administratorski pregled'), ENT_QUOTES, 'UTF-8') ?></a>
<h2><?= htmlspecialchars(fcc_t('Razgovori i ocjene Coacha'), ENT_QUOTES, 'UTF-8') ?></h2>
<?php
$reviewUser=max(0,(int)($_GET['review_user']??0));
$recentThreads=fcc_partner_rows("SELECT c.fcc_ai_conversation_id,c.user_id,u.name,c.datetime FROM fcc_ai_conversations c JOIN users u ON u.user_id=c.user_id WHERE c.scope='internal_coach' AND c.assistant_type='coach' ".($reviewUser?'AND c.user_id=? ':'')."ORDER BY c.fcc_ai_conversation_id DESC LIMIT 20",$reviewUser?[$reviewUser]:[]);
?>
<details class="fp-panel" <?= $reviewUser?'open':'' ?>><summary><?= htmlspecialchars(fcc_t('Otvori razgovor za pregled'), ENT_QUOTES, 'UTF-8') ?></summary><p><?= htmlspecialchars(fcc_t('Prikazano je do 20 najnovije otvorenih razgovora. Izostanak negativne ocjene ne znači da odgovor ne treba doraditi.'), ENT_QUOTES, 'UTF-8') ?></p><?php foreach($recentThreads as $thread): ?><a class="fp-link" href="<?= url('partner/admin?coach=1&thread='.(int)$thread['fcc_ai_conversation_id']) ?>"><?= $h($thread['name']) ?> · <?= $h($thread['datetime']) ?> <?= htmlspecialchars(fcc_t('UTC'), ENT_QUOTES, 'UTF-8') ?></a><?php endforeach ?></details>
<?php if($conversation): ?><a class="fp-link" href="<?= url('partner/admin?coach=1') ?>"><?= htmlspecialchars(fcc_t('Ocjene iz svih razgovora →'), ENT_QUOTES, 'UTF-8') ?></a><?php endif ?>
<p><?= htmlspecialchars(fcc_t('Pregledaj označeni odgovor i pitanje na koje se odnosi. Ocjene ostaju spremljene za usporedbu i doradu Coacha.'), ENT_QUOTES, 'UTF-8') ?></p>
<?php $qualityRows=fcc_partner_rows("SELECT m.fcc_ai_message_id,m.fcc_ai_conversation_id,m.meta,m.datetime,u.name FROM fcc_ai_messages m JOIN fcc_ai_conversations c ON c.fcc_ai_conversation_id=m.fcc_ai_conversation_id JOIN users u ON u.user_id=c.user_id WHERE c.scope='internal_coach' AND c.assistant_type='coach' AND m.role='assistant' ORDER BY m.fcc_ai_message_id DESC LIMIT 100");$qualityRows=array_values(array_filter($qualityRows,static fn($r)=>!empty((json_decode($r['meta']??'{}',true)?:[])['learning']['signals']))); ?>
<?php if($qualityRows): ?><details class="fp-panel"><summary><?= htmlspecialchars(fcc_t('Signali za pregled u posljednjih 100 odgovora:'), ENT_QUOTES, 'UTF-8') ?> <?= count($qualityRows) ?></summary><p><?= htmlspecialchars(fcc_t('Ovo su naznake za pregled komunikacije, ne ocjene suradnika.'), ENT_QUOTES, 'UTF-8') ?></p><?php foreach($qualityRows as $row): ?><a class="fp-link" href="<?= url('partner/admin?coach=1&thread='.(int)$row['fcc_ai_conversation_id'].'#message-'.(int)$row['fcc_ai_message_id']) ?>"><?= $h($row['name']) ?> · <?= $h($row['datetime']) ?> <?= htmlspecialchars(fcc_t('UTC'), ENT_QUOTES, 'UTF-8') ?></a><?php endforeach ?></details><?php endif ?>
<nav class="fp-filter-row" aria-label="<?= htmlspecialchars(fcc_t('Filtriraj ocjene'), ENT_QUOTES, 'UTF-8') ?>"><?php foreach(fcc_localize_copy(['all'=>fcc_t('Sve ocjene'),'open'=>fcc_t('Čeka pregled'),'down'=>'Palac dolje','up'=>'Palac gore']) as $value=>$label): ?><a class="fp-button fp-button-outline" <?= $filter===$value?'aria-current="page"':'' ?> href="<?= url('partner/admin?coach=1&rating='.$value.$conversation_query) ?>"><?= $label ?></a><?php endforeach ?></nav>
<?php if(!$ratings): ?><section class="fp-panel"><p><?= htmlspecialchars(fcc_t('Nema ocjena za ovaj odabir.'), ENT_QUOTES, 'UTF-8') ?></p></section><?php endif ?>
<?php foreach($ratings as $rating): ?><article class="fp-panel fp-coach-review" id="coach-feedback-<?= (int)$rating['fcc_ai_message_feedback_id'] ?>">
 <div class="fp-section-title fp-wrap-heading"><h3><?= $h($rating['name']) ?></h3><span class="fp-status"><?= $rating['feedback_type']==='up'?fcc_t('Palac gore'):($rating['status']==='resolved'?fcc_t('Pregledano'):fcc_t('Palac dolje')) ?></span></div>
 <small><?= $h($rating['last_datetime']) ?> <?= htmlspecialchars(fcc_t('UTC'), ENT_QUOTES, 'UTF-8') ?></small>
 <?php if($rating['reason']): ?><p><strong><?= $h(fcc_ai_get_feedback_reason_label($rating['reason'],'hr')) ?></strong></p><?php endif ?>
 <?php if($rating['note']): ?><p><?= $h($rating['note']) ?></p><?php endif ?>
 <details><summary><?= htmlspecialchars(fcc_t('Pitanje i ocijenjeni odgovor'), ENT_QUOTES, 'UTF-8') ?></summary><h4><?= htmlspecialchars(fcc_t('Pitanje suradnika'), ENT_QUOTES, 'UTF-8') ?></h4><p class="fp-coach-review-text"><?= $h($rating['question']??'') ?></p><h4><?= htmlspecialchars(fcc_t('Odgovor Coacha'), ENT_QUOTES, 'UTF-8') ?></h4><p class="fp-coach-review-text"><?= $h($rating['content']) ?></p><?php $response_meta=json_decode($rating['response_meta']??'{}',true)?:[]; if(!empty($response_meta['coach_prompt_version'])): ?><small><?= htmlspecialchars(fcc_t('Verzija odgovora:'), ENT_QUOTES, 'UTF-8') ?> <?= $h($response_meta['coach_prompt_version']) ?></small><?php endif ?></details>
 <div class="fp-actions"><a class="fp-link" href="<?= $h(url('partner/admin?coach=1&thread='.(int)$rating['fcc_ai_conversation_id'])) ?>"><?= htmlspecialchars(fcc_t('Cijeli razgovor →'), ENT_QUOTES, 'UTF-8') ?></a>
 <?php if($rating['feedback_type']==='down'&&$rating['status']==='new'): ?><form method="post"><?= $token ?><input type="hidden" name="action" value="coach_feedback_resolve"><input type="hidden" name="feedback_id" value="<?= (int)$rating['fcc_ai_message_feedback_id'] ?>"><button class="fp-button fp-button-outline"><?= htmlspecialchars(fcc_t('Označi pregledano'), ENT_QUOTES, 'UTF-8') ?></button></form><?php endif ?></div>
</article><?php endforeach ?>
<?php if($has_more): ?><a class="fp-button fp-button-outline" href="<?= url('partner/admin?coach=1&rating='.$filter.$conversation_query.'&before='.(int)end($ratings)['fcc_ai_message_feedback_id']) ?>"><?= htmlspecialchars(fcc_t('Starije ocjene →'), ENT_QUOTES, 'UTF-8') ?></a><?php endif ?>
